import {readFile} from 'node:fs/promises';
import path from 'node:path';
import {NextRequest, NextResponse} from 'next/server';

// Generated by `npm run cv`; next.config.ts ships them with this function.
const CV_FILES = {
	en: 'juan-gomez-cv-en.pdf',
	es: 'juan-gomez-cv-es.pdf',
} as const;

export async function GET(request: NextRequest) {
	const locale = request.nextUrl.searchParams.get('locale') || 'en';

	if (locale !== 'en' && locale !== 'es') {
		return NextResponse.json({error: 'Invalid locale'}, {status: 400});
	}

	const filename = CV_FILES[locale];

	try {
		const pdf = await readFile(path.join(process.cwd(), 'public', 'resume', filename));

		return new NextResponse(new Uint8Array(pdf), {
			headers: {
				'Content-Type': 'application/pdf',
				'Content-Disposition': `attachment; filename="${filename}"`,
				'Cache-Control': 'public, max-age=3600',
			},
		});
	} catch (error) {
		console.error('Error reading CV:', error);
		return NextResponse.json({error: 'Internal server error'}, {status: 500});
	}
}
